export interface QueuedAction {
  id: string;
  type: string;
  payload: unknown;
  createdAt: number;
}

export class ActionQueue {
  private items: QueuedAction[] = [];
  enqueue(action: Omit<QueuedAction, 'id' | 'createdAt'>): QueuedAction {
    const item: QueuedAction = { ...action, id: `q-${this.items.length}`, createdAt: Date.now() };
    this.items.push(item);
    return item;
  }
  pending(): QueuedAction[] {
    return this.items.slice();
  }
}
